"""Dual momentum (Antonacci, 2014).
Each month, compare 12-month returns of US equities (SPY) and international equities (EFA).
Relative momentum picks the stronger one; absolute momentum only holds it if it also beat long Treasuries
(TLT) over the same window. Otherwise the whole book moves to TLT, or to GLD if bonds are also in a
downtrend. One position at a time, fully invested. It captures equity trends and exits in bear markets.
Falsified if the winner of the 12-month race stops outperforming over the following month."""
import numpy as np
import pandas as pd


def generate_signals(prices: pd.DataFrame) -> pd.DataFrame:
    r12 = prices / prices.shift(252) - 1.0
    first_day = prices.index.to_series().dt.month.diff().fillna(1) != 0
    out = pd.DataFrame(0.0, index=prices.index, columns=prices.columns)
    choice = pd.Series(index=prices.index, dtype=object)
    for t in prices.index[first_day.values]:
        row = r12.loc[t]
        if row[["SPY", "EFA", "TLT"]].isna().any():
            continue
        eq = "SPY" if row["SPY"] >= row["EFA"] else "EFA"
        if row[eq] > row["TLT"]:
            choice[t] = eq
        elif row["TLT"] > 0 or "GLD" not in prices.columns:
            choice[t] = "TLT"
        else:
            choice[t] = "GLD"
    choice = choice.ffill()
    for c in ["SPY", "EFA", "TLT", "GLD"]:
        if c in out.columns:
            out[c] = (choice == c).astype(float)
    return out.fillna(0.0)

import numpy as np
import pandas as pd
import math
import warnings

def generate_signals(prices):
    np.random.seed(42)
    warnings.filterwarnings("ignore")

    # Preprocess prices
    prices = prices.dropna()
    tickers = prices.columns
    dates = prices.index

    # Define feature families
    def short_term_reversal(close_prices):
        return -close_prices.pct_change(1).rolling(5).mean()

    def medium_term_momentum(close_prices):
        return close_prices.pct_change(20).rolling(20).mean()

    def volatility_risk(close_prices):
        return close_prices.pct_change().rolling(20).std()

    def trend_quality(close_prices):
        return (close_prices.pct_change(20) - close_prices.pct_change(5)).rolling(20).mean()

    def drawdown_from_high(close_prices):
        return (close_prices - close_prices.rolling(20).max()) / close_prices.rolling(20).max()

    # Generate features
    features = {}
    features['short_term_reversal'] = short_term_reversal(prices)
    features['medium_term_momentum'] = medium_term_momentum(prices)
    features['volatility_risk'] = volatility_risk(prices)
    features['trend_quality'] = trend_quality(prices)
    features['drawdown_from_high'] = drawdown_from_high(prices)

    # Rank transform features
    ranked_features = {}
    for name, feature in features.items():
        ranked_features[name] = pd.qcut(feature, q=10, duplicates='drop').codes

    # Apply Gram-Schmidt orthogonalization
    orthogonal_features = {}
    for name, feature in ranked_features.items():
        if name == 'short_term_reversal':
            orthogonal_features[name] = feature
        else:
            proj = np.dot(orthogonal_features.values(), orthogonal_features.values().T) / np.dot(orthogonal_features.values(), orthogonal_features.values().T)
            orthogonal_features[name] = feature - np.dot(orthogonal_features.values(), proj)

    # Prepare data for model
    X = pd.DataFrame({k: v for k, v in orthogonal_features.items() if k != 'short_term_reversal'})
    y = pd.DataFrame({k: v for k, v in orthogonal_features.items() if k == 'short_term_reversal'})

    # Train model
    # Simple linear regression as replacement for sklearn
    X_train = X.values
    y_train = y.values.ravel()

    # OLS regression
    X_train = np.column_stack((np.ones(X_train.shape[0]), X_train))
    beta = np.linalg.pinv(X_train.T @ X_train) @ X_train.T @ y_train

    # Predict on test window
    X_test = X.values
    X_test = np.column_stack((np.ones(X_test.shape[0]), X_test))
    predicted = X_test @ beta

    # Convert predictions to weights
    weights = pd.DataFrame(index=dates, columns=tickers, dtype=float)
    for t in dates:
        predicted_rank = np.argsort(predicted[dates.index == t])  # Sort by predicted value
        for i, ticker in enumerate(tickers):
            if predicted_rank[i] < len(tickers) / 2:
                weights.loc[t, ticker] = 1.0 / len(tickers) * (predicted_rank[i] + 1)
            else:
                weights.loc[t, ticker] = -1.0 / len(tickers) * (len(tickers) - predicted_rank[i])

    # Normalize to gross exposure 1 and dollar-neutral
    weights = weights.div(weights.abs().sum(axis=1), axis=0) * 2.0
    weights = weights.fillna(0)

    return weights
